const j = $input.first().json || {};
const op = String(j.op || '').toLowerCase();
const ok = ['callback','link','desconectar','listar','criar','editar','remover','status','convidar','renomear'];
return [{ json: {
  op: ok.includes(op) ? op : 'status',
  numero: String(j.numero || '').replace(/\D/g, '').slice(0, 15),
  usuario_id: /^[0-9a-f-]{36}$/i.test(String(j.usuario_id || '')) ? String(j.usuario_id) : null,
  code: String(j.code || '').slice(0, 512),
  redirect_uri: String(j.redirect_uri || 'https://dynoapp.com.br/conectar-agenda'),
  de: j.de || null, ate: j.ate || null, dias: Math.min(Math.max(Number(j.dias) || 7, 1), 200), busca: String(j.busca || '').slice(0, 80),
  max: Math.min(Math.max(Number(j.max) || 40, 1), 250),
  event_id: String(j.event_id || '').replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 200),
  titulo: String(j.titulo || '').slice(0, 200), inicio: j.inicio || null, fim: j.fim || null,
  local: String(j.local || '').slice(0, 300), descricao: String(j.descricao || '').slice(0, 1000), dia_inteiro: j.dia_inteiro === true,
  // 10/10: reunião com sala do Google Meet e convite aos participantes
  meet: j.meet === true,
  participantes: (Array.isArray(j.participantes) ? j.participantes : []).slice(0, 20).map(x => ({ nome: String((x && x.nome) || '').slice(0, 80), email: String((x && x.email) || '').trim().slice(0, 120), whatsapp: String((x && x.whatsapp) || '').replace(/\D/g, '').slice(0, 15) })),
  canal: String(j.canal || '').slice(0, 20),
  // 10/10: várias contas Google (pessoal e institucional): qual conta usar e se deve perguntar quando houver mais de uma
  conta: String(j.conta || '').trim().slice(0, 120),
  perguntar_conta: j.perguntar_conta === true,
  nome: String(j.nome || '').trim().slice(0, 40)
} }];

const t = $('Google: trocar código').first().json || {};
const cal = $input.first().json || {};
const p = $('Pedido').first().json;
const email = /@/.test(String(cal.id || '')) ? String(cal.id) : null;
return [{ json: { p_usuario: p.usuario_id, p_refresh: t.refresh_token || null, p_access: t.access_token, p_expira_seg: Number(t.expires_in) || 3600, p_email: email, p_escopos: String(t.scope || '') } }];

const r = $input.first().json || {};
const g = $('Preparar gravação').first().json || {};
const NL = String.fromCharCode(10);
const podeEditar = /calendar\.events/.test(g.p_escopos || '');
// 10/10: várias contas Google (pessoal e institucional)
const contas = Array.isArray(r.contas) ? r.contas : [];
const nomeConta = c => '*' + (c.rotulo || 'Agenda') + '* (' + c.email + ')';
let t = '📅 Oi' + (r.nome ? ', ' + r.nome : '') + '! Aqui é a Dina.' + NL + NL;
if (r.ok !== true && r.erro === 'limite') {
  t += '⚠️ Você já tem 3 contas Google conectadas: ' + contas.map(nomeConta).join(', ') + '. Esse é o limite.' + NL + NL + 'Para trocar uma delas, diga *desconectar agenda* e o nome da conta (ex.: _desconectar a agenda Pessoal_) e depois *conectar agenda* de novo.';
  return [{ json: { number: r.numero, text: String.fromCharCode(8203) + t, delay: 800 } }];
}
if (contas.length > 1) {
  t += '✅ *Mais uma agenda conectada*: ' + nomeConta({ rotulo: r.rotulo, email: r.email }) + '.' + NL + NL +
    'Agora você tem ' + contas.length + ' agendas comigo:' + NL + contas.map(c => '• ' + nomeConta(c)).join(NL) + NL + NL +
    'Quando você pedir para marcar uma reunião, um compromisso, uma tarefa ou um lembrete, eu pergunto em qual agenda marcar. Se já disser na hora (ex.: _"marca na ' + (r.rotulo || 'Institucional') + '"_), eu marco direto.' + NL + NL +
    'Quer outro nome para uma delas? Diga, por exemplo: _"chama a agenda ' + (r.rotulo || 'Institucional') + ' de Trabalho"_.';
  if (!podeEditar) t += NL + NL + '⚠️ Nesta conta a permissão para *ver e editar eventos* ficou desmarcada, então nela eu só consigo ler a agenda. Para corrigir, diga *conectar agenda* de novo e deixe as opções marcadas.';
} else {
  t += '✅ *Google Agenda conectada*' + (r.email ? ' (' + r.email + ')' : '') + '.' + NL + NL;
  if (podeEditar) t += 'A partir de agora eu vejo seus compromissos e posso marcar eventos direto na sua agenda. Experimente: _"o que tenho amanhã?"_ ou _"marca dentista quinta às 15h"_.';
  else t += '⚠️ A permissão para *ver e editar eventos* ficou desmarcada, então só consigo ler a agenda. Para eu marcar compromissos, diga *conectar agenda* de novo e deixe as opções marcadas.';
  t += NL + NL + 'Tem outra conta Google, como a do trabalho? Diga *conectar outra agenda* que eu mando o link e você escolhe a outra conta no Google.';
}
t += NL + NL + 'Para desconectar quando quiser, é só dizer *desconectar agenda*.';
return [{ json: { number: r.numero, text: String.fromCharCode(8203) + t, delay: 800 } }];

const r = $('Supabase: salvar conexão').first().json || {};
// 10/10: limite de 3 contas Google: a página mostra falha e a Dina explica no WhatsApp
if (r.ok !== true) return [{ json: { ok: false, erro: r.erro || 'gravar' } }];
return [{ json: { ok: true, nome: r.nome || '', email: r.email || '', rotulo: r.rotulo || '', n_contas: r.n_contas || 1 } }];

let t = {}; try { t = $('Google: trocar código').first().json || {}; } catch (e) {}
let s = {}; try { s = $('Supabase: salvar conexão').first().json || {}; } catch (e) {}
const erro = s.erro ? s.erro : (t.error ? 'google' : 'gravar');
return [{ json: { ok: false, erro } }];

const r = $('Supabase: desconectar').first().json || {};
// 10/10: várias contas: escolher (quando não deu para saber qual desconectar), e-mails desconectados e as que ficaram
return [{ json: { ok: r.ok !== false, conectado: r.conectado === true, escolher: r.escolher === true, email: r.email || '', emails: r.emails || [], restantes: r.restantes || [], contas: r.contas || [], conta_pedida: r.conta_pedida || '' } }];

const p = $('Pedido').first().json;
const t = $('Supabase: token').first().json || {};
let access = t.valido ? t.access_token : null;
let novo = null; try { novo = $('Google: renovar token').first().json; } catch (e) { novo = null; }
if (novo && novo.access_token) access = novo.access_token;
let desconectou = false; try { desconectou = $('Supabase: guardar token').first().json.desconectado === true; } catch (e) {}
if (!access) return [{ json: { op: 'sem_token', ok: false, conectado: !desconectou, erro: desconectou ? 'revogado' : 'renovar', eventos: [], texto: '' } }];
// 10/10: leva junto qual conta foi usada e a lista das contas conectadas (sem tokens)
return [{ json: Object.assign({}, p, { access, email: t.email || '', rotulo: t.rotulo || '', n_contas: Number(t.n_contas) || 1, contas: Array.isArray(t.contas) ? t.contas : [] }) }];

const r = $input.first().json || {};
const t = $('Supabase: token').first().json || {};
if (r.access_token) return [{ json: { p_usuario: t.usuario_id, p_access: r.access_token, p_expira_seg: Number(r.expires_in) || 3600, p_erro: null, p_email: t.email || null } }];
const txt = JSON.stringify(r);
return [{ json: { p_usuario: t.usuario_id, p_access: null, p_expira_seg: null, p_erro: /invalid_grant/.test(txt) ? 'invalid_grant' : txt.slice(0, 250), p_email: t.email || null } }];

// 10/10: com mais de uma conta Google, quando não deu para saber qual usar, devolve as contas para a Dina perguntar.
const t = $('Supabase: token').first().json || {};
if (t.escolher === true) return [{ json: { ok: false, conectado: true, erro: 'escolher_conta', contas: t.contas || [], n_contas: t.n_contas || 0, conta_pedida: t.conta_pedida || '', eventos: [], texto: '' } }];
return [{ json: { ok: true, conectado: false, eventos: [], texto: '' } }];

const r = $input.first().json || {};
// 10/10: qual conta Google foi listada (para juntar as agendas pessoal e institucional)
const tk = $('Token pronto').first().json || {};
const info = { conta: tk.email || '', rotulo: tk.rotulo || '', n_contas: Number(tk.n_contas) || 1, contas: tk.contas || [] };
if (r.error && !r.items) return [{ json: Object.assign({ ok: false, conectado: true, erro: 'google', eventos: [], texto: '' }, info) }];
const TZ = 'America/Sao_Paulo';
const DIAS = ['', 'seg', 'ter', 'qua', 'qui', 'sex', 'sáb', 'dom'];
const eventos = (r.items || []).filter((e) => e.status !== 'cancelled').map((e) => {
  const inteiro = !!(e.start && e.start.date);
  const ini = inteiro ? DateTime.fromISO(e.start.date, { zone: TZ }) : DateTime.fromISO(e.start.dateTime).setZone(TZ);
  const fim = inteiro ? DateTime.fromISO(e.end.date, { zone: TZ }).minus({ days: 1 }) : DateTime.fromISO(e.end.dateTime).setZone(TZ);
  return { conta: info.conta, id: e.id, titulo: e.summary || '(sem título)', inicio: ini.toISO(), fim: fim.toISO(), dia_inteiro: inteiro, local: e.location || '', descricao: String(e.description || '').slice(0, 500), link: e.htmlLink || '', recorrente: !!e.recurringEventId,
    linha: DIAS[ini.weekday] + ' ' + ini.toFormat('dd/MM') + ' ' + (inteiro ? '(dia inteiro)' : ini.toFormat('HH:mm') + '–' + fim.toFormat('HH:mm')) + ' ' + (e.summary || '(sem título)') + (e.location ? ' — ' + e.location : '') };
});
const texto = eventos.length ? eventos.slice(0, 40).map((e) => '• ' + e.linha).join(String.fromCharCode(10)) : 'Nenhum compromisso no período.';
return [{ json: Object.assign({ ok: true, conectado: true, eventos, texto }, info) }];

