parameters.jsCode:
const r = $input.first().json || {};
const tk = $('Token pronto').first().json || {};
const info = { conta: tk.email || '', rotulo: tk.rotulo || '', n_contas: Number(tk.n_contas) || 1 };
if (!r.id) return [{ json: Object.assign({ ok: false, conectado: true, erro: /insufficient|forbidden|403/i.test(JSON.stringify(r)) ? 'permissao' : 'google' }, info) }];
// 10/10: link da sala do Google Meet (quando a reunião pediu sala)
const cd = r.conferenceData || {};
const video = (Array.isArray(cd.entryPoints) ? cd.entryPoints : []).find(e => e && e.entryPointType === 'video');
const meet = r.hangoutLink || (video && video.uri) || '';
return [{ json: { ...info, ok: true, conectado: true, id: r.id, link: r.htmlLink || '', titulo: r.summary || '', meet, meet_status: (cd.createRequest && cd.createRequest.status && cd.createRequest.status.statusCode) || '', inicio: (r.start && (r.start.dateTime || r.start.date)) || '', fim: (r.end && (r.end.dateTime || r.end.date)) || '' } }];

const j = $input.first().json || {};
if (j.op === 'sem_token') return [{ json: { ok: false, conectado: j.conectado, erro: j.erro, eventos: [], texto: '' } }];
return [{ json: { ok: true, conectado: true, email: j.email || '', rotulo: j.rotulo || '', n_contas: Number(j.n_contas) || 1, contas: j.contas || [] } }];

const r = $input.first().json || {};
if (!r.id) return [{ json: { ok: false, conectado: true, erro: /insufficient|forbidden|403/i.test(JSON.stringify(r)) ? 'permissao' : (/404|not.?found/i.test(JSON.stringify(r)) ? 'nao_encontrado' : 'google') } }];
return [{ json: { ok: true, conectado: true, id: r.id, link: r.htmlLink || '', titulo: r.summary || '' } }];

const r = $input.first().json || {};
const s = JSON.stringify(r);
if (r.error && !/410|404|deleted/i.test(s)) return [{ json: { ok: false, conectado: true, erro: /insufficient|forbidden|403/i.test(s) ? 'permissao' : 'google' } }];
return [{ json: { ok: true, conectado: true } }];

// 10/10: resultado do convite da reunião. E-mail: pelo no-reply@dynoapp.com.br (convite_email_via = noreply) ou pelo próprio Google (google). WhatsApp: fila de envios.
const c = $('Supabase: preparar convite').first().json || {};
let g = null; try { g = $('Google: convidar').first().json; } catch (e) { g = null; }
let envios = null; try { envios = $('E-mail: convite (no-reply)').all().map(i => i.json || {}); } catch (e) { envios = null; }
let emailOk = null, emailErro = null;
if (envios && envios.length) {
  const falhas = envios.filter(e => e.error || !(Array.isArray(e.accepted) && e.accepted.length));
  emailOk = falhas.length === 0;
  if (!emailOk) emailErro = 'smtp';
} else if (g) {
  emailOk = !!g.id;
  if (!emailOk) emailErro = /insufficient|forbidden|403/i.test(JSON.stringify(g)) ? 'permissao' : 'google';
} else if (c.via === 'noreply' && Array.isArray(c.emails_novos) && c.emails_novos.length) {
  emailOk = false; emailErro = 'smtp';
}
return [{ json: Object.assign({ ok: false }, c, { conectado: true, email_ok: emailOk, email_erro: emailErro }) }];

// 10/10: convite da reunião por e-mail pelo no-reply@dynoapp.com.br, com arquivo .ics (abre como convite no Gmail/Outlook).
// Mesmo UID do evento do Google: quem já tem o evento na agenda não fica com cópia duplicada.
const c = $('Supabase: preparar convite').first().json || {};
const g0 = $input.first().json || {};
const g = g0.id ? g0 : {};
const TZ = 'America/Sao_Paulo';
const novos = Array.isArray(c.emails_novos) ? c.emails_novos : [];
const todos = Array.isArray(c.emails) ? c.emails : novos;
const esc = s => String(s || '').replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
const icsEsc = s => String(s || '').replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\r?\n/g, '\\n');
const fold = l => { let o = ''; let s = l; while (s.length > 70) { o += s.slice(0, 70) + '\r\n '; s = s.slice(70); } return o + s; };
const iniISO = (g.start && g.start.dateTime) || c.inicio;
if (!iniISO || !novos.length) return [];
const ini = DateTime.fromISO(String(iniISO)).setZone(TZ);
const fimISO = (g.end && g.end.dateTime) || c.fim;
const fim = fimISO ? DateTime.fromISO(String(fimISO)).setZone(TZ) : ini.plus({ hours: 1 });
const u = d => d.toUTC().toFormat("yyyyLLdd'T'HHmmss'Z'");
const titulo = String(c.titulo || g.summary || 'Reunião');
const quem = String(c.quem || 'Seu contato');
const primeiro = quem.split(' ')[0];
const meet = String(c.meet || g.hangoutLink || '');
const orgEmail = String((g.organizer && g.organizer.email) || c.quem_email || 'no-reply@dynoapp.com.br');
const uid = String(g.iCalUID || (String(c.event_id || 'reuniao') + '@dynoapp.com.br'));
const dia = ini.setLocale('pt-BR').toFormat("cccc, dd 'de' LLLL");
const hora = ini.toFormat('HH:mm') + '–' + fim.toFormat('HH:mm');
const desc = quem + ' te convidou para esta reunião.' + (meet ? '\nGoogle Meet: ' + meet : '') + '\n\nEnviado pelo Dyno (dynoapp.com.br).';
const linhas = [
  'BEGIN:VCALENDAR', 'PRODID:-//Dyno//Reunioes//PT-BR', 'VERSION:2.0', 'CALSCALE:GREGORIAN', 'METHOD:REQUEST',
  'BEGIN:VEVENT', 'UID:' + uid, 'DTSTAMP:' + u(DateTime.now()), 'DTSTART:' + u(ini), 'DTEND:' + u(fim),
  'SEQUENCE:' + (Number(g.sequence) || 0), 'STATUS:CONFIRMED',
  'SUMMARY:' + icsEsc(titulo), 'DESCRIPTION:' + icsEsc(desc),
  ...(meet ? ['LOCATION:' + icsEsc(meet), 'URL:' + meet] : []),
  'ORGANIZER;CN=' + icsEsc(quem) + ':mailto:' + orgEmail,
  ...todos.map(e => 'ATTENDEE;CUTYPE=INDIVIDUAL;ROLE=REQ-PARTICIPANT;PARTSTAT=NEEDS-ACTION;RSVP=TRUE;CN=' + icsEsc(e) + ':mailto:' + e),
  'BEGIN:VALARM', 'ACTION:DISPLAY', 'DESCRIPTION:' + icsEsc(titulo), 'TRIGGER:-PT10M', 'END:VALARM',
  'END:VEVENT', 'END:VCALENDAR'
];
const ics = linhas.map(fold).join('\r\n') + '\r\n';
const gcal = 'https://calendar.google.com/calendar/render?action=TEMPLATE&text=' + encodeURIComponent(titulo) + '&dates=' + u(ini) + '/' + u(fim) + '&details=' + encodeURIComponent(desc);
const botao = meet ? '<p style="margin:24px 0"><a href="' + esc(meet) + '" style="background:#12A866;color:#ffffff;text-decoration:none;font-weight:600;padding:12px 22px;border-radius:999px;display:inline-block">Entrar no Google Meet</a></p><p style="margin:0 0 4px;color:#5b6270;font-size:13px">Link da sala: <a href="' + esc(meet) + '" style="color:#0B1A3A">' + esc(meet) + '</a></p>' : '';
const html = '<div style="background:#F6F4EF;padding:24px 12px;font-family:Arial,Helvetica,sans-serif;color:#0D1424">' +
  '<div style="max-width:520px;margin:0 auto;background:#ffffff;border-radius:14px;padding:28px 24px;border:1px solid #e6e2d8">' +
  '<p style="margin:0 0 6px;font-size:13px;color:#5b6270;letter-spacing:.04em;text-transform:uppercase">Convite para reunião</p>' +
  '<h1 style="margin:0 0 16px;font-size:22px;line-height:1.3">' + esc(titulo) + '</h1>' +
  '<p style="margin:0 0 16px;font-size:15px"><b>' + esc(quem) + '</b> te convidou para uma reunião.</p>' +
  '<table role="presentation" style="border-collapse:collapse;font-size:15px"><tr><td style="padding:4px 12px 4px 0;color:#5b6270">Quando</td><td style="padding:4px 0"><b>' + esc(dia) + '</b><br>' + esc(hora) + ' (horário de Brasília)</td></tr></table>' +
  botao +
  '<p style="margin:20px 0 0;font-size:13px;color:#5b6270">O convite (.ics) está anexado: abra para adicionar à sua agenda. Se preferir, <a href="' + esc(gcal) + '" style="color:#0B1A3A">adicione ao Google Agenda</a>.</p>' +
  '<hr style="border:none;border-top:1px solid #eee;margin:22px 0 14px">' +
  '<p style="margin:0;font-size:12px;color:#8a8f99">Enviado pelo Dyno, assistente de ' + esc(primeiro) + ' no WhatsApp. Para falar sobre a reunião, responda este e-mail: a resposta vai direto para ' + esc(primeiro) + '.</p>' +
  '</div></div>';
const b64 = Buffer.from(ics, 'utf8').toString('base64');
return novos.map(to => ({
  json: { to, subject: 'Convite: ' + titulo + ' · ' + ini.setLocale('pt-BR').toFormat('dd/LL') + ' às ' + ini.toFormat('HH:mm'), html, replyTo: (g.organizer && g.organizer.email) || c.quem_email || 'suporte@dynoapp.com.br' },
  binary: { ics: { data: b64, mimeType: 'text/calendar', fileExtension: 'ics', fileName: 'convite.ics' } }
}));

// 10/10: com várias contas Google, revoga cada token desconectado (um item por token).
const r = $input.first().json || {};
const lista = (Array.isArray(r.tokens) ? r.tokens : (r.refresh_token ? [r.refresh_token] : [])).filter(Boolean);
if (!lista.length) return [{ json: { refresh_token: null } }];
return lista.map(t => ({ json: { refresh_token: t } }));
